do $$ declare r uuid;x public.rma_requests%rowtype;paid numeric;stock_before bigint; begin
 perform pg_temp.assert_true(not has_function_privilege('anon','public.admin_perform_rma_review_action_v2(uuid,text,jsonb,text)','EXECUTE'),'anonymous review v2 denied');
 perform pg_temp.assert_true(not has_function_privilege('authenticated','private.rma_waiver_reason(jsonb)','EXECUTE'),'private reason function denied');
 r:=pg_temp.make_rma(1,'pending','wallet_credit','submitted');
 x:=public.admin_perform_rma_review_action_v2(r,'approve','{"return_mode":"refund_only","waiver_reason_code":"no_recovery_value"}','approve-refund-only');
 perform pg_temp.assert_true(x.status='approved' and x.return_waived_at is not null and x.refund_completed_at is null,'approval exempts return but does not pay or close');
 perform pg_temp.assert_true((select count(*) from public.notification_events where rma_request_id=r and body like 'No return required%')=1,'approval sends one accurate no-return notification');
 perform public.admin_perform_rma_review_action_v2(r,'approve','{"return_mode":"refund_only","waiver_reason_code":"no_recovery_value"}','approve-refund-only');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_review_action_v2(%L,''approve'',''{"return_mode":"return_required"}'',''approve-refund-only'')',r),'same approval key cannot change mode');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v2(%L,''mark_received'',''{"quantity":1}'',''fake-receipt-after-waiver'')',r),'no receipt after waiver');
 select balance into paid from public.customer_wallets where customer_id=x.customer_id;
 x:=public.admin_perform_rma_simple_action_v2(r,'execute_refund','{"refund_method":"wallet_credit","refund_amount":8}','refund-only-wallet');
 perform pg_temp.assert_true(x.status='closed' and x.closed_at is not null and x.received_at is null and x.inventory_disposition='pending','refund-only wallet closes without receipt or stock');
 perform pg_temp.assert_true((select balance from public.customer_wallets where customer_id=x.customer_id)=paid+8,'wallet exact credit');
 perform public.admin_perform_rma_simple_action_v2(r,'execute_refund','{"refund_method":"wallet_credit","refund_amount":8}','refund-only-wallet');
 perform pg_temp.assert_true((select count(*) from public.customer_wallet_transactions where metadata->>'rma_request_id'=r::text)=1,'closed retry does not duplicate credit');
 perform pg_temp.assert_true((select count(*) from public.admin_audit_events where entity_id=r::text and action='rma.auto_close')=1,'one completion audit');
 r:=pg_temp.make_rma(1,'pending','wallet_credit','submitted');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_review_action_v2(%L,''approve'',''{"return_mode":"refund_only","waiver_reason_code":"other"}'',''missing-other-reason'')',r),'other requires nonblank note');
 x:=public.admin_perform_rma_review_action_v2(r,'approve','{"return_mode":"refund_only","waiver_reason_code":"other","reason":"损坏"}','approve-short-note');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v2(%L,''execute_refund'',''{"refund_method":"cash","refund_amount":11,"cash_paid":true}'',''too-much-refund-only'')',r),'overcap refunds rollback');
 select * into x from public.rma_requests where id=r;
 perform pg_temp.assert_true(x.status='approved' and x.refund_completed_at is null,'failed refund does not close or pay');
 x:=public.admin_perform_rma_simple_action_v2(r,'execute_refund','{"refund_method":"cash","refund_amount":10,"cash_paid":true}','refund-only-cash');
 perform pg_temp.assert_true(x.status='closed' and x.refund_method='cash' and x.refund_transaction_id is null,'cash closes without wallet transaction');
 r:=pg_temp.make_rma(1,'pending','wallet_credit','approved');
 x:=public.admin_perform_rma_simple_action_v2(r,'waive_return','{"waiver_reason_code":"return_cost_high"}','convert-approved-only');
 perform pg_temp.assert_true(x.status='approved' and x.return_waived_at is not null,'approved case changes mode before money');
 r:=pg_temp.make_rma(1,'pending','wallet_credit','approved');
 update public.rma_requests set customer_shipped_at=now() where id=r;
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v2(%L,''waive_return'',''{"waiver_reason_code":"no_recovery_value"}'',''cannot-waive-in-transit'')',r),'in-transit retains physical obligations');
 r:=pg_temp.make_rma(1,'failed','wallet_credit','received');
 x:=public.admin_perform_rma_simple_action_v2(r,'execute_refund','{"refund_method":"cash","refund_amount":10,"cash_paid":true}','pay-before-disposition');
 perform pg_temp.assert_true(x.status='refunded','unprocessed received goods do not auto close');
 perform public.admin_perform_rma_action_v4(r,'mark_scrapped','{"quantity":1,"batch_code":"TEST-RETURN","location":"Milano"}','final-stock-disposition');
 select * into x from public.rma_requests where id=r;
 perform pg_temp.assert_true(x.status='closed','last physical operation closes paid return');
 r:=pg_temp.make_rma(1,'failed','wallet_credit','received');
 perform public.admin_perform_rma_action_v4(r,'mark_scrapped','{"quantity":1,"batch_code":"TEST-RETURN","location":"Milano"}','stock-before-payment');
 select * into x from public.rma_requests where id=r;
 perform pg_temp.assert_true(x.status='received','stock processing alone does not close unpaid case');
 x:=public.admin_perform_rma_simple_action_v2(r,'execute_refund','{"refund_method":"cash","refund_amount":10,"cash_paid":true}','pay-after-disposition');
 perform pg_temp.assert_true(x.status='closed','last money operation closes disposed return');
end $$;
rollback;
